import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uv, mix, attribute, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    InstancedMesh,
    IcosahedronGeometry,
    PlaneGeometry,
    AmbientLight,
    DirectionalLight,
    AdditiveBlending,
    DoubleSide,
  } = ctx.THREE;

  const root = new Group();

  // ---------- Backdrop Gradient Plane ----------
  const bgGeom = new PlaneGeometry(7, 6);
  const bgMat = new MeshStandardNodeMaterial();
  bgMat.transparent = true;
  bgMat.side = DoubleSide;
  // vertical gradient from #0b0b10 (top) to #16161d (bottom)
  bgMat.colorNode = mix(color('#0b0b10'), color('#16161d'), uv().y);
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  root.add(bgMesh);

  // ---------- Lights ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, 1, 1).normalize();
  root.add(keyLight);

  const rimLight = new DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-1, -0.5, -1).normalize();
  root.add(rimLight);

  // ---------- Particle Geometry ----------
  const icoGeom = new IcosahedronGeometry(0.012, 0);

  // ---------- Field Particles ----------
  const totalParticles = 1200;
  const coreCount = 90;
  const fieldCount = totalParticles - coreCount;

  const fieldMat = new MeshStandardNodeMaterial();
  fieldMat.transparent = true;
  fieldMat.depthWrite = false;
  fieldMat.colorNode = color('#e8ecf2');
  fieldMat.metalnessNode = float(0);
  fieldMat.roughnessNode = float(1);
  // per‑instance opacity based on z position
  fieldMat.opacityNode = attribute('instanceOpacity');

  const fieldMesh = new InstancedMesh(icoGeom, fieldMat, fieldCount);
  const fieldMatrix = new Float32Array(fieldCount * 16);
  const opacityArray = new Float32Array(fieldCount);

  for (let i = 0; i < fieldCount; i++) {
    const x = (Math.random() * 2 - 1) * 3; // width 6
    const y = (Math.random() * 2 - 1) * 2; // height 4
    const z = (Math.random() * 2 - 1) * 2.5 - 1.5; // depth 5, centered at -1.5

    const matrix = new THREE.Matrix4().makeTranslation(x, y, z);
    matrix.toArray(fieldMatrix, i * 16);

    const t = Math.max(0, Math.min(1, -z / 5)); // 0 at z=0, 1 at z=-5
    const opacity = 0.9 + t * (0.15 - 0.9);
    opacityArray[i] = opacity;
  }
  fieldMesh.instanceMatrix.set(fieldMatrix);
  fieldMesh.instanceMatrix.needsUpdate = true;
  fieldMesh.geometry.setAttribute('instanceOpacity', new THREE.InstancedBufferAttribute(opacityArray, 1));
  root.add(fieldMesh);

  // ---------- Core Particles ----------
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.transparent = true;
  coreMat.blending = AdditiveBlending;
  coreMat.depthWrite = false;
  coreMat.colorNode = color('#ff2a38');
  coreMat.emissiveNode = color('#ff2a38');
  coreMat.emissiveIntensity = 1.5;
  coreMat.metalnessNode = float(0);
  coreMat.roughnessNode = float(1);

  const coreMesh = new InstancedMesh(icoGeom, coreMat, coreCount);
  const coreMatrix = new Float32Array(coreCount * 16);
  for (let i = 0; i < coreCount; i++) {
    const phi = Math.random() * Math.PI * 2;
    const costheta = Math.random() * 2 - 1;
    const u = Math.random();
    const theta = Math.acos(costheta);
    const r = Math.cbrt(u) * 0.5; // radius 0.5
    const x = r * Math.sin(theta) * Math.cos(phi);
    const y = r * Math.sin(theta) * Math.sin(phi);
    const z = r * Math.cos(theta);
    const matrix = new THREE.Matrix4().makeTranslation(x, y, z);
    matrix.toArray(coreMatrix, i * 16);
  }
  coreMesh.instanceMatrix.set(coreMatrix);
  coreMesh.instanceMatrix.needsUpdate = true;
  root.add(coreMesh);

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 124,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, txtOpts);
    // Position according to role
    if (item.role === 'hero') {
      txt.position.set(0, 0.5, 0.5);
    } else if (item.role === 'subhead') {
      txt.position.set(0, -0.25, 0.5);
    } else if (item.role === 'caption') {
      txt.position.set(0, -2.25, 0.5);
    } else {
      txt.position.set(0, 0, 0.5);
    }
    root.add(txt);
  }

  // ---------- Cinematic Primitives ----------
  const activePrimitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const p of config.cinematicPrimitives) {
      const prim = ctx.primitives[p.name];
      if (prim) {
        const instance = prim(root, p.params);
        activePrimitives.push(instance);
      }
    }
  }

  // ---------- Core Pulse Animation ----------
  const pulseTL = gsap.timeline({ repeat: -1, y: 'none' });
  pulseTL
    .to(coreMat, { emissiveIntensity: 1.8, duration: 5, ease: 'sine.inOut' })
    .to(coreMat, { emissiveIntensity: 1.5, duration: 5, ease: 'sine.inOut' });

  // ---------- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // dispose geometries & materials
    bgGeom.dispose();
    bgMat.dispose();
    icoGeom.dispose();
    fieldMesh.geometry.dispose();
    fieldMesh.material.dispose();
    coreMesh.geometry.dispose();
    coreMesh.material.dispose();

    // kill GSAP timelines
    pulseTL.kill();

    // primitive cleanups
    for (const p of activePrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
  };

  return root;
}
